//! Type alias chain and type-level resolution.

use std::collections::BTreeMap;
use std::sync::Arc;

use camino::Utf8Path;
use compact_str::CompactString;
use rustc_hash::{FxHashMap, FxHashSet};

use crate::types::*;

use super::chain::resolve_props_chain;
use super::collected::resolve_collected_type;
use super::primitives::union_of;
use super::{ResolutionContext, ResolvedChain};

/// Resolve a `CollectedTypeAlias` as a props chain.
#[allow(clippy::too_many_arguments)]
pub(super) fn resolve_type_alias_chain(
    alias: &CollectedTypeAlias,
    _consuming_file: &Utf8Path,
    mapping: &ComponentMapping,
    ctx: &ResolutionContext,
    state: &mut ResolveState,
    depth: u8,
) -> ResolvedChain {
    match alias {
        // Delegate to the generic CollectedType→chain resolver, which already
        // handles Named (interfaces/type aliases), Object (inline literals),
        // Intersection, and Union targets. Previously this arm only matched
        // `Named` and silently dropped everything else (e.g. an inline
        // `{ x: string }` object literal used directly as props), which lost
        // the whole component's props with no diagnostic.
        CollectedTypeAlias::Passthrough { target, file_path } => {
            resolve_base_as_chain(target, file_path, mapping, ctx, state, depth)
        }

        CollectedTypeAlias::Omit { base, keys, file_path } => {
            // The base is read once, knowing the keys this `Omit` (and any around it) takes away, so each source in it
            // collapses by the members that reach the component (`ResolutionContext::collapses`). The keys are read
            // first in a detached state; their diagnostics come from the read after the base, as before.
            let mut detached = state.detached();
            let known = resolve_key_set(keys, file_path, mapping, ctx, &mut detached, depth);
            let outer = state.omitted.clone();
            if let Some(known) = known {
                let mut all: FxHashSet<String> = outer.as_deref().cloned().unwrap_or_default();
                all.extend(known);
                state.omitted = Some(Arc::new(all));
            }
            let mut chain = resolve_base_as_chain(base, file_path, mapping, ctx, state, depth);
            state.omitted = outer;
            let Some(omitted) = resolve_key_set_or_warn("Omit", keys, file_path, mapping, ctx, state, depth) else {
                return chain;
            };
            let omitted_set: FxHashSet<&str> = omitted.iter().map(String::as_str).collect();
            chain.props.retain(|p| !omitted_set.contains(p.name.as_str()));
            chain.notable.retain(|p| !omitted_set.contains(p.name.as_str()));
            // Record omitted keys in the relevant inheritance layer.
            for layer in &mut chain.inheritance {
                // A collapsed layer names the props it holds, so an omitted one is no longer held.
                if !layer.members.is_empty() {
                    let held = layer.members.len();
                    layer.members.retain(|name| !omitted_set.contains(name.as_str()));
                    layer.total_props =
                        layer.total_props.saturating_sub(u32::try_from(held - layer.members.len()).unwrap_or(0));
                }
                for key in &omitted {
                    if !layer.omitted.contains(key) {
                        layer.omitted.push(key.clone());
                    }
                }
            }
            chain
        }

        CollectedTypeAlias::Pick { base, keys, file_path } => {
            let expand_all = state.expand_all;
            state.expand_all = expand_all || ctx.can_collapse();
            let mut chain = resolve_base_as_chain(base, file_path, mapping, ctx, state, depth);
            state.expand_all = expand_all;
            let Some(picked) = resolve_key_set_or_warn("Pick", keys, file_path, mapping, ctx, state, depth) else {
                chain.props.clear();
                return chain;
            };
            let picked_set: FxHashSet<&str> = picked.iter().map(String::as_str).collect();
            chain.props.retain(|p| picked_set.contains(p.name.as_str()));
            chain.notable.retain(|p| picked_set.contains(p.name.as_str()));
            // The base was a `composes` entry with no picked props (React's declarations stay out of the run unless the
            // attributes are `full`, and then a base interface can still list none of them): read them from React.
            let missing: Vec<String> =
                picked.iter().filter(|name| !chain.props.iter().any(|prop| &prop.name == *name)).cloned().collect();
            if !missing.is_empty() {
                chain.props.extend(react_picked_props(base, &missing, file_path, mapping, ctx, state, depth));
            }
            // Only the picked attributes remain: each is read from the element's layer, which then has nothing left to list.
            for name in &picked {
                if chain.props.iter().any(|prop| &prop.name == name) {
                    continue;
                }
                let attribute = chain.inheritance.iter().find_map(|layer| {
                    layer_attribute(layer, name, ctx, state, depth).filter(|_| layer.html_element.is_some())
                });
                if let Some(attribute) = attribute {
                    chain.props.push(ctx.share(attribute));
                }
            }
            chain.inheritance.retain(|layer| layer.html_element.is_none());
            chain
        }

        CollectedTypeAlias::Partial { base, file_path } => {
            let mut chain = resolve_base_as_chain(base, file_path, mapping, ctx, state, depth);
            // Make all props optional, a collapsed source's notable ones too.
            for prop in chain.props.iter_mut().chain(chain.notable.iter_mut()).filter(|prop| prop.required) {
                Arc::make_mut(prop).required = false;
            }
            chain
        }

        CollectedTypeAlias::Required { base, file_path } => {
----
        type_name: &str,
        members: impl Iterator<Item = &'a str>,
        depth: u8,
        state: &ResolveState,
    ) -> bool {
        if depth == 0 || state.expand_all {
            return false;
        }
        let reaching = match &state.omitted {
            Some(omitted) => members.filter(|name| !omitted.contains(*name)).count(),
            None => members.count(),
        };
        self.collapse_inherited_props.collapses(self.is_dependency_file(file), file.as_str(), type_name, reaching)
    }
}

/// `layers` with each collapsed source once: a source reached through two paths (`Big & Omit<Big, "a">`) holds the
/// members that reach through either, and omits only what every path omits. A member counts once, as the collapse
/// decision counts it (`CollapseInheritedProps::collapses`).
fn one_layer_per_collapsed_source(layers: Vec<InheritedLayer>) -> Vec<InheritedLayer> {
    let mut merged: Vec<InheritedLayer> = Vec::with_capacity(layers.len());
    for layer in layers {
        let same = merged.iter_mut().find(|seen| {
            !seen.members.is_empty() && seen.type_name == layer.type_name && seen.file_name == layer.file_name
        });
        match same {
            Some(seen) if !layer.members.is_empty() => {
                for member in layer.members {
                    if !seen.members.contains(&member) {
                        seen.members.push(member);
                    }
                }
                seen.omitted.retain(|key| layer.omitted.contains(key) && !seen.members.contains(key));
                seen.total_props = u32::try_from(seen.members.len()).unwrap_or(u32::MAX);
            }
            _ => merged.push(layer),
        }
    }
    merged
}

/// Whether `global` declares an interface, or an object-literal alias, of more than `LARGE_API_SOURCE` members: a
/// project source the default mode collapses.
fn declares_large_source(global: &GlobalSourceData) -> bool {
    use crate::types::options::LARGE_API_SOURCE;
    global.interfaces.values().any(|interface| interface.props.len() > LARGE_API_SOURCE)
        || global.type_aliases.values().any(|alias| {
            matches!(alias, CollectedTypeAlias::Passthrough { target: CollectedType::Object(fields), .. }
                if fields.len() > LARGE_API_SOURCE)
        })
}

