"""Scratch: per-component differences between two outputs (props, notable, layers' members), grouped."""
import collections
import json
import sys

a, b = (json.load(open(p)) for p in sys.argv[1:3])
ca, cb = a['components'], b['components']
print('components', len(ca), len(cb), 'only base', len(set(ca) - set(cb)), 'only new', len(set(cb) - set(ca)))
kinds = collections.Counter()
examples = collections.defaultdict(list)
for key in sorted(set(ca) & set(cb)):
    x, y = ca[key], cb[key]
    if x == y:
        continue
