"""Scratch: per-component differences between two canonical outputs (props by name, notable, layer members)."""
import collections
import json
import sys

docs = [json.load(open(p)) for p in sys.argv[1:3]]


def view(doc, entry):
    props = {doc['props'][i]['name']: doc['props'][i] for i in entry.get('props', [])}
    layers = {}
    for layer in entry.get('inheritance', []):
        members = layer.get('members', [])
        if isinstance(members, str):
            members = doc['nameLists'][members]
        layers[layer['typeName']] = (set(members), layer.get('totalProps'))
    return props, set(entry.get('notableInherited', {})), layers


kinds = collections.Counter()
examples = collections.defaultdict(list)
ca, cb = docs[0]['components'], docs[1]['components']
for key in sorted(set(ca) & set(cb)):
    (px, nx, lx), (py, ny, ly) = view(docs[0], ca[key]), view(docs[1], cb[key])
    sig = []
    for name in sorted(set(py) - set(px)):
        parent = (py[name].get('parent') or {}).get('name')
        sig.append(f'+{name}({parent})')
    for name in sorted(set(px) - set(py)):
        sig.append(f'-{name}')
    for name in sorted(set(px) & set(py)):
        if px[name] != py[name]:
            sig.append(f'~{name}' + str([k for k in set(px[name]) | set(py[name]) if px[name].get(k) != py[name].get(k)]))
    if nx != ny:
        sig.append(f'notable {sorted(nx ^ ny)}')
    for t in sorted(set(lx) | set(ly)):
        if lx.get(t) != ly.get(t):
            mx, my = lx.get(t, (set(), 0)), ly.get(t, (set(), 0))
            sig.append(f'layer {t} -{sorted(mx[0] - my[0])} +{sorted(my[0] - mx[0])} total {mx[1]}->{my[1]}')
    if sig:
        s = ' '.join(sig)
        kinds[s] += 1
        examples[s].append(key.split(' ')[0])
for s, n in kinds.most_common(60):
    print(n, s[:300], examples[s][:3])

